parameters.inputSchema:
{
  "type": "object",
  "required": ["ambient_c_base", "load_factor", "narrative"],
  "properties": {
    "ambient_c_base": { "type": "number", "minimum": 5, "maximum": 40, "description": "Machine-room ambient temperature in degrees Celsius" },
    "load_factor": { "type": "number", "minimum": 0.7, "maximum": 1.4, "description": "Traffic intensity, 1.0 being a normal day" },
    "narrative": { "type": "string", "description": "One short line describing the conditions" }
  }
}

parameters.jsCode:
// Deterministic. The model invents the SCENARIO; every number below is derived
// here, in code, from that scenario plus facts about each lift.
//
// Three rules this node exists to enforce:
//
//  1. Units are Celsius / rpm / Nm / hours, never the model's Kelvin feature
//     space. A language model asked for "a machine temperature" answers 300 on
//     some runs and 27 on others, and both survive the ingest schema. Deriving
//     the numbers here removes that whole class of failure.
//
//  2. `recorded_at` is stamped HERE, not in the HTTP node that follows. n8n
//     retries a failed node by re-running THAT node with the same input, so a
//     timestamp computed upstream is carried unchanged into the retry and the
//     backend recognises the batch as the same readings. Computed downstream,
//     every retry would be a new batch and would weigh twice in the window
//     average the risk score is built from.
//
//  3. The spread has to match the space the model was trained on. A first
//     version of this node produced torque across an 8 Nm band and rpm across
//     58, and the fleet came back with 68 of 70 lifts scored 0.0000 — the model
//     was being shown one operating point wearing 70 different names. The
//     distributions below mirror `_synthesise_features` in
//     backend/ml/generate_predictions.py, which is what produced the committed
//     predictions.json, so online and offline generation agree by construction.

const fallbackScenario = { ambient_c_base: 24, load_factor: 1.0, narrative: 'Fallback: the agent did not return a usable scenario.' };
let scenario;
try {
  const raw = $('Invent scenario').first().json;
  scenario = raw.output ?? raw;
} catch (e) {
  scenario = fallbackScenario;
}
if (typeof scenario.ambient_c_base !== 'number' || typeof scenario.load_factor !== 'number') {
  scenario = fallbackScenario;
}

const fleet = $('Fetch fleet').all().map((i) => i.json);
const recordedAt = new Date().toISOString();

const ambientBase = Math.min(Math.max(scenario.ambient_c_base, 5), 40);
const load = Math.min(Math.max(scenario.load_factor, 0.7), 1.4);

const seed = `${ambientBase}|${load}`;

// Two hashes, and the split is the whole point.
//
// `character` is a property of the LIFT and is independent of the scenario: the
// same lift has the same operating character on every tick. `tick` varies with
// the scenario, and is deliberately small.
//
// A first version folded the scenario into a single hash, so every lift was
// re-rolled from scratch each tick, and the scenario's load factor multiplied
// the whole fleet's torque at once. Both effects are global, and the inference
// run averages readings over a 24-hour window — so the per-lift spread cancelled
// out and the fleet flattened. Observed directly: one tick gave 3 high / 1
// medium / 66 low, the next gave 70 low, and the window average of the two was
// flat. Over 96 ticks a day it would always be flat.
//
// So: the lift's character carries the spread (sigma 12, wider than any
// scenario term), the scenario shifts it a little, and the tick adds a light
// jitter. Averaging many ticks now converges on the lift, not on the scenario.
function hashOf(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return ((h >>> 0) % 100000) / 100000;
}
const character = (id, salt) => hashOf(`${id}|${salt}`);
const tick = (id, salt) => hashOf(`${id}|${seed}|${salt}`);

// Box-Muller, not a sum of uniforms.
//
// The obvious deterministic stand-in for rng.gauss() is to add three uniforms
// and standardise. It has the right mean and sigma and the wrong TAILS: the sum
// is bounded, so the result can never fall further than 1.5 sigma from the
// mean. That matters here more than it sounds. In this model the high-risk
// signature is LOW torque together with exhausted motor life - the committed
// predictions.json has ELV-001 at 9.5 Nm scoring 0.80 - and 9.5 Nm is a -3
// sigma draw from a mean of 40. A truncated distribution simply never lands
// there, so the generated fleet came out uniformly healthy and the demo showed
// seventy low-risk lifts. Box-Muller keeps the tails.
function gaussOf(fn, id, salt, mean, sigma) {
  const u1 = Math.min(Math.max(fn(id, salt + '1'), 1e-6), 1 - 1e-6);
  const u2 = fn(id, salt + '2');
  return mean + sigma * Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
}

const clamp = (n, lo, hi) => Math.min(Math.max(n, lo), hi);
const r1 = (n) => Math.round(n * 10) / 10;

const readings = fleet
  .filter((e) => e.in_model_scope)
  .map((e) => {
    const floors = e.floor_count || 5;

    // The lift's own operating character: scenario-independent, sigma 12, and
    // wider than anything the scenario contributes. This is what survives being
    // averaged over the inference window.
    const torqueBase = gaussOf(character, e.id, 't', 40 + floors * 0.3, 12);
    // The day's conditions nudge it; they no longer scale it.
    const torque = clamp(torqueBase + (load - 1) * 8 + gaussOf(tick, e.id, 'tn', 0, 2), 3, 80);
    // Speed follows from torque at roughly constant power, exactly as offline.
    const rpm = clamp((2860 / Math.max(torque, 1)) * 9.549 + gaussOf(tick, e.id, 'r', 0, 50), 1168, 2860);

    const ambient = r1(clamp(ambientBase + gaussOf(tick, e.id, 'a', 0, 2), -60, 120));
    const motor = r1(clamp(ambient + gaussOf(character, e.id, 'm', 10, 1), -60, 120));

    return {
      elevator_id: e.id,
      recorded_at: recordedAt,
      ambient_temperature_c: ambient,
      motor_temperature_c: motor,
      motor_speed_rpm: Math.round(rpm),
      load_torque_nm: r1(torque)
      // motor_run_hours_cumulative is deliberately NOT sent.
      //
      // The real formula is hourly_trips_avg x active_hours x run_min_per_trip
      // x 365 x age_years, and `hourly_trips_avg` is not in the GET
      // /api/elevators response - this producer cannot compute it. The column is
      // nullable for exactly this case: when it is absent the inference service
      // derives consumed motor life from the lift's own building type, usage and
      // age, which it holds and we do not, using the same function the offline
      // script uses so online and offline agree.
      //
      // An earlier version invented a duty factor of 0.06 to fill the field in.
      // That overrode a correct fallback with a worse guess, and it flattened the
      // fleet: consumed motor life is what separates a worn lift from a healthy
      // one in this model, and a fabricated constant gives every lift the same
      // wear curve.
    };
  });

return [{ json: { source: 'n8n-telemetry-ingest', readings, _narrative: scenario.narrative } }];
